"""Emitter, selector shapes, key-set parity, determinism and freshness of the generated files."""

from __future__ import annotations

import copy
import json
import unittest
from pathlib import Path

from institutional_theme.audits import parity
from institutional_theme.midad import build, colour, deviations, emit, model

REPO = Path(__file__).resolve().parents[3]
TOKENS = build.load_tokens(REPO / "design" / "tokens.json")
MODEL = model.load_model()
FIXTURE = json.loads((REPO / "design" / "reference" / "tokens.resolved.json").read_text(encoding="utf-8"))


def _family_checks(name: str, text: str, family: str = "palette") -> list[parity.Check]:
	return parity.check_family(name, text, family, color_scheme=False)


class Emitter(unittest.TestCase):
	KEYS = ["--ins-a", "--ins-b"]
	LIGHT = {"--ins-a": "#ffffff", "--ins-b": "#000000"}
	DARK = {"--ins-a": "#111111", "--ins-b": "#eeeeee"}

	def test_blocks_use_the_selector_shapes_of_adr_0003(self):
		base = emit.emit_family("base", self.KEYS, self.LIGHT, self.DARK, color_scheme=True)
		self.assertIn('html:root,\nhtml [data-theme="light"] {', base)
		self.assertIn('html:root[data-theme="dark"],\nhtml [data-theme="dark"] {', base)
		self.assertIn('@media (prefers-color-scheme: dark) {\n\thtml:root[data-theme="automatic"] {', base)
		palette = emit.emit_family("palette", self.KEYS, self.LIGHT, self.DARK)
		self.assertIn('html:root[dir],\nhtml[dir] [data-theme="light"] {', palette)
		self.assertIn('html:root[dir][data-theme="dark"],\nhtml[dir] [data-theme="dark"] {', palette)
		self.assertIn('\thtml:root[dir][data-theme="automatic"] {', palette)

	def test_color_scheme_in_light_dark_and_automatic(self):
		base = emit.emit_family("base", self.KEYS, self.LIGHT, self.DARK, color_scheme=True)
		blocks = parity.parse_blocks(base)
		self.assertEqual([parity._scheme(b) for b in blocks], [["light"], ["dark"], [], ["light dark"]])
		self.assertEqual(blocks[3].media, None)

	def test_color_scheme_is_absent_unless_asked_for(self):
		palette = emit.emit_family("palette", self.KEYS, self.LIGHT, self.DARK)
		self.assertNotRegex(palette, r"(?<!-)color-scheme\s*:")

	def test_one_key_list_gives_three_blocks_with_the_same_keys(self):
		blocks = parity.parse_blocks(emit.emit_family("palette", self.KEYS, self.LIGHT, self.DARK))
		self.assertEqual([parity._keys(b) for b in blocks], [self.KEYS] * 3)

	def test_automatic_block_repeats_the_dark_values(self):
		blocks = parity.parse_blocks(emit.emit_family("palette", self.KEYS, self.LIGHT, self.DARK))
		self.assertEqual(blocks[2].declarations, blocks[1].declarations)

	def test_a_key_missing_from_either_mode_is_an_error(self):
		with self.assertRaises(KeyError):
			emit.emit_family("palette", self.KEYS, {"--ins-a": "#fff"}, self.DARK)
		with self.assertRaises(KeyError):
			emit.emit_family("palette", self.KEYS, self.LIGHT, {"--ins-b": "#000"})

	def test_scale_blocks(self):
		text = emit.emit_scale([("--ins-x", "1px")], [("--ins-x", "2px")], [("--ins-x", "3px")])
		blocks = parity.parse_blocks(text)
		self.assertEqual(blocks[0].selectors, ("html:root[dir]",))
		self.assertEqual(blocks[1].selectors, ('html:root[dir][data-ins-density="compact"]',))
		self.assertEqual(
			blocks[2].selectors,
			("html:root[dir][data-theme-mode][data-ins-density]", "html:root[dir][data-theme-mode]"),
		)
		self.assertEqual(blocks[2].media, "(pointer: coarse)")

	def test_literals(self):
		self.assertEqual(emit.emit_literals([("T", [("a", "1px")])]), "// T\n$a: 1px;\n")

	def test_rtl_wrapper(self):
		self.assertEqual(emit.wrap_rtl_ignore("a {}\n"), "/*rtl:begin:ignore*/\na {}\n/*rtl:end:ignore*/\n")

	def test_header(self):
		self.assertTrue(emit.header().startswith("// generated by institutional_theme.midad.build"))
		self.assertTrue(emit.header("/*").endswith("do not edit */\n"))


class ParityOfEveryPreset(unittest.TestCase):
	def _palette_text(self, palette: model.Palette) -> str:
		return model.palette_css(MODEL, palette, header="")

	def test_every_preset_emits_equal_key_sets_in_all_three_blocks(self):
		for name in MODEL["palettes"]["presets"]:
			with self.subTest(preset=name):
				text = self._palette_text(model.palette(MODEL, name))
				self.assertEqual([c for c in _family_checks(name, text) if not c.passed], [])

	def test_a_sample_custom_preset_emits_equal_key_sets(self):
		for primary, accent in (("#7a1fa2", "#b8860b"), ("#00796b", None), (None, "#c0392b")):
			with self.subTest(primary=primary, accent=accent):
				result = model.custom_preset(primary, accent, MODEL)
				text = self._palette_text(result.palette)
				self.assertEqual([c for c in _family_checks("custom", text) if not c.passed], [])

	def test_a_key_that_changes_in_one_mode_is_written_in_both(self):
		text = self._palette_text(model.palette(MODEL, "graphite"))
		light, dark = parity.parse_blocks(text)[:2]
		self.assertIn("--ins-on-primary", parity._keys(light))  # white in light, ink.950 in dark
		self.assertEqual(parity._keys(light), parity._keys(dark))

	def test_midad_emits_no_palette_overrides(self):
		blocks = parity.parse_blocks(self._palette_text(model.palette(MODEL, "midad")))
		self.assertEqual([b.declarations for b in blocks], [[], [], []])

	def test_a_broken_family_is_detected(self):
		text = emit.emit_family("palette", ["--ins-a"], {"--ins-a": "#fff"}, {"--ins-a": "#000"})
		broken = text.replace("\t--ins-a: #000;", "\t--ins-b: #000;", 1)
		self.assertTrue([c for c in _family_checks("broken", broken) if not c.passed])


class GeneratedFiles(unittest.TestCase):
	@classmethod
	def setUpClass(cls):
		cls.files = build.render_all(TOKENS)

	def test_build_is_deterministic(self):
		again = build.render_all(TOKENS)
		self.assertEqual(
			{p: t.encode() for p, t in self.files.items()}, {p: t.encode() for p, t in again.items()}
		)

	def test_files_on_disk_are_not_stale(self):
		self.assertEqual(build.check_all(self.files), [])

	def test_every_generated_file_starts_with_the_header(self):
		for path, text in self.files.items():
			if path.suffix == ".scss":
				self.assertTrue(text.startswith(f"// {emit.HEADER_TEXT}\n"), path.name)
		self.assertTrue(self.files[build.MODEL_PATH].startswith('{\n\t"_generated": "generated by'))

	def test_tokens_scss_midad_values_equal_the_fixture_byte_for_byte(self):
		text = self.files[build.SCSS_DIR / "_tokens.scss"]
		light, dark = parity.parse_blocks(text)[:2]
		values = {"light": dict(light.declarations), "dark": dict(dark.declarations)}
		checked = 0
		for mode in ("light", "dark"):
			for name, approved in FIXTURE["sem"][mode].items():
				if approved.startswith("#") and len(approved) == 7:
					expected = deviations.expected(FIXTURE, mode, name)
					self.assertEqual(values[mode][f"--ins-{name}"], expected, f"{mode} {name}")
					checked += 1
		self.assertEqual(checked, 242)

	def test_tokens_scss_carries_the_fixture_primitives_the_map_uses(self):
		light = dict(parity.parse_blocks(self.files[build.SCSS_DIR / "_tokens.scss"])[0].declarations)
		for ramp, steps in FIXTURE["prim"].items():
			for step, expected in steps.items():
				key = f"--ins-{ramp}-{step}"
				if key in light:
					self.assertEqual(light[key], expected, key)
		self.assertIn("--ins-slate-300", light)
		self.assertIn("--ins-blue-500", light)

	def test_literals_hold_the_light_midad_values(self):
		text = self.files[build.SCSS_DIR / "_literals.scss"]
		self.assertIn("$ins-primary: #1b5086;", text)
		self.assertIn("$ins-surface-scrim: rgba(9, 16, 24, 0.45);", text)
		self.assertIn("$ins-space-4: 16px;", text)
		self.assertNotIn("var(", text)

	def test_no_generated_stylesheet_uses_forbidden_syntax(self):
		for path, text in self.files.items():
			if path.suffix == ".scss":
				self.assertEqual(parity.check_forbidden(path.name, text).problems, [], path.name)

	def test_palette_bundles_exist_only_for_shipped_non_default_presets(self):
		names = {p.name for p in self.files if p.name.startswith("ins_palette_")}
		expected = {
			f"ins_palette_{n}.bundle.scss"
			for n in MODEL["palettes"]["shipped"]
			if n != MODEL["palettes"]["default"]
		}
		self.assertEqual(names, expected)

	def test_palette_bundles_are_wrapped_in_the_rtl_ignore_pair(self):
		for path, text in self.files.items():
			if path.name.startswith("ins_palette_"):
				self.assertIn("/*rtl:begin:ignore*/", text)
				self.assertTrue(text.rstrip().endswith("/*rtl:end:ignore*/"))

	def test_the_parity_audit_passes_on_the_files_on_disk(self):
		checks = parity.audit_model(MODEL) + parity.audit_files(MODEL, build.SCSS_DIR)
		self.assertEqual([c for c in checks if not c.passed], [])

	def test_a_stale_file_is_detected(self):
		tampered = dict(self.files)
		path = build.SCSS_DIR / "_scale.scss"
		tampered[path] = tampered[path].replace("32px", "33px", 1)
		self.assertEqual(build.check_all(tampered), [path])


class Shipping(unittest.TestCase):
	"""The build decides which presets ship; a failing preset gets no bundle."""

	def test_a_preset_below_a_minimum_is_dropped_with_the_failing_pair(self):
		midad, graphite = model.palette(MODEL, "midad"), model.palette(MODEL, "graphite")
		best = None
		for mode in model.MODES:
			for fg in ("primary-text", "text-brand", "focus", "primary", "chart-1"):
				for bg in ("surface-base", "surface-sunken", "surface-hover"):
					gap = colour.contrast(midad.colour(fg, mode), midad.colour(bg, mode)) - colour.contrast(
						graphite.colour(fg, mode), graphite.colour(bg, mode)
					)
					if best is None or gap > best[0]:
						best = (gap, fg, bg, mode)
		gap, fg, bg, mode = best
		self.assertGreater(gap, 0.05, "graphite never has less contrast than midad on these pairs")
		limit = round(colour.contrast(midad.colour(fg, mode), midad.colour(bg, mode)) - gap / 2, 2)
		tokens = copy.deepcopy(TOKENS)
		tokens["contrast"]["groups"].append(
			{"name": "Test", "min": limit, "target": limit, "fg": [fg], "bg": [bg]}
		)
		files = build.render_all(tokens)
		built = json.loads(files[build.MODEL_PATH])
		self.assertEqual(built["palettes"]["shipped"][0], "midad")
		self.assertIn("graphite", built["palettes"]["dropped"])
		self.assertTrue(
			any(fg in reason and bg in reason for reason in built["palettes"]["dropped"]["graphite"])
		)
		self.assertNotIn(build.SCSS_DIR / "ins_palette_graphite.bundle.scss", files)
		report = files[build.AUDITS_DIR / "presets.txt"]
		self.assertIn("graphite: DROPPED", report)
		self.assertIn(fg, report)

	def test_the_default_preset_is_never_dropped(self):
		tokens = copy.deepcopy(TOKENS)
		tokens["contrast"]["groups"].append(
			{"name": "Impossible", "min": 30, "target": 30, "fg": ["text-strong"], "bg": ["surface-base"]}
		)
		with self.assertRaises(build.BuildError) as raised:
			build.render_all(tokens)
		self.assertIn("midad", str(raised.exception))

	def test_umber_is_dropped_by_the_status_check_and_forest_ships(self):
		self.assertIn("umber", MODEL["palettes"]["dropped"])
		self.assertTrue(any("status" in r for r in MODEL["palettes"]["dropped"]["umber"]))
		self.assertIn("forest", MODEL["palettes"]["shipped"])
		report = (build.AUDITS_DIR / "presets.txt").read_text(encoding="utf-8")
		self.assertIn("umber: DROPPED", report)

	def test_a_leftover_bundle_of_a_dropped_preset_is_stale(self):
		files = build.render_all(TOKENS)
		leftover = build.SCSS_DIR / "ins_palette_umber.bundle.scss"
		self.assertFalse(leftover.exists())
		self.assertNotIn(leftover, files)


class DeskScope(unittest.TestCase):
	def test_only_desk_is_a_scope(self):
		frappe = {"vars": {"--x": {"both": "@primary", "scope": "web"}}}
		with self.assertRaises(build.BuildError):
			build._frappe_vars(frappe)
		ok = build._frappe_vars(
			{"vars": {"--x": {"both": "@primary", "scope": "desk"}, "--y": {"both": "@primary"}}}
		)
		self.assertEqual(ok["--x"]["scope"], "desk")
		self.assertNotIn("scope", ok["--y"])

	def test_the_web_map_drops_a_desk_variable_and_the_full_map_keeps_it(self):
		marked = copy.deepcopy(MODEL)
		for entry in marked["frappe"]["vars"].values():
			entry.pop("scope", None)
		name = next(iter(marked["frappe"]["vars"]))
		marked["frappe"]["vars"][name]["scope"] = "desk"
		full = [n for n, _ in model.frappe_map(marked).declarations["light"]]
		web = [n for n, _ in model.frappe_map(marked, model.WEB).declarations["light"]]
		self.assertIn(name, full)
		self.assertNotIn(name, web)
		self.assertEqual([n for n in full if n != name], web)
		self.assertEqual(model.desk_only(marked), [name])

	def test_the_shipped_model_marks_the_desk_only_variables_in_model_json(self):
		marked = [
			n
			for n, e in TOKENS["frappe"]["vars"].items()
			if not n.startswith("_") and e.get("scope") == "desk"
		]
		self.assertEqual(model.desk_only(MODEL), marked)
		self.assertGreaterEqual(len(marked), 50)


class LightOnlyPartials(unittest.TestCase):
	"""The website bundle imports the light-only partials; they must equal the light blocks."""

	PAIRS = (("_tokens.scss", "_tokens_light.scss"), ("_frappe_map.scss", "_frappe_map_light.scss"))

	@staticmethod
	def _light_block(text: str) -> str:
		start = text.index("html:root")
		return text[start : text.index("}\n", start) + 2]

	def test_light_file_is_the_light_block_of_the_full_file(self):
		files = build.render_all(TOKENS)
		full_text, light_text = (files[build.SCSS_DIR / name] for name in self.PAIRS[0])
		block = self._light_block(full_text)
		self.assertTrue(light_text.endswith("\n\n" + block))
		self.assertEqual(light_text.count("{"), 1)
		self.assertEqual(light_text.splitlines()[0], full_text.splitlines()[0])

	def test_website_map_is_the_light_block_without_the_desk_only_names(self):
		files = build.render_all(TOKENS)
		full_text, web_text = (files[build.SCSS_DIR / name] for name in self.PAIRS[1])
		full = parity.parse_blocks(full_text)[0]
		web = parity.parse_blocks(web_text)[0]
		desk_only = set(model.desk_only(MODEL))
		self.assertTrue(desk_only, "the map marks desk-only variables")
		self.assertEqual(web.selectors, full.selectors)
		self.assertEqual(web.declarations, [d for d in full.declarations if d[0] not in desk_only])
		self.assertTrue(desk_only.isdisjoint(prop for prop, _ in web.declarations))
		self.assertTrue(desk_only <= {prop for prop, _ in full.declarations})
		self.assertEqual(web_text.splitlines()[0], full_text.splitlines()[0])

	def test_the_full_map_keeps_every_desk_only_name_in_light_and_dark(self):
		fmap = model.frappe_map(MODEL)
		self.assertEqual(
			[n for n, _ in fmap.declarations["light"]], [n for n, _ in fmap.declarations["dark"]]
		)
		names = {n for n, _ in fmap.declarations["light"]}
		self.assertTrue(set(model.desk_only(MODEL)) <= names)
		web = {n for n, _ in model.frappe_map(MODEL, model.WEB).declarations["light"]}
		self.assertEqual(names - web, set(model.desk_only(MODEL)))

	def test_light_files_have_no_dark_or_automatic_selector(self):
		files = build.render_all(TOKENS)
		for _, light in self.PAIRS:
			text = files[build.SCSS_DIR / light]
			self.assertNotIn("@media", text)
			blocks = parity.parse_blocks(text)
			self.assertEqual(len(blocks), 1)
			self.assertIsNone(blocks[0].media)
			for selector in blocks[0].selectors:
				self.assertNotRegex(selector, r"dark|automatic")
			self.assertEqual(len(blocks[0].selectors), 2)

	def test_light_tokens_keep_color_scheme_light_and_map_has_none(self):
		files = build.render_all(TOKENS)
		tokens = files[build.SCSS_DIR / "_tokens_light.scss"]
		self.assertEqual(parity._scheme(parity.parse_blocks(tokens)[0]), ["light"])
		self.assertNotRegex(files[build.SCSS_DIR / "_frappe_map_light.scss"], r"(?<!-)color-scheme\s*:")

	def test_light_files_are_deterministic_and_fresh(self):
		first, second = build.render_all(TOKENS), build.render_all(TOKENS)
		for _, light in self.PAIRS:
			path = build.SCSS_DIR / light
			self.assertEqual(first[path], second[path])
			self.assertEqual(path.read_text(encoding="utf-8"), first[path])

	def test_emit_light_family_equals_first_block_of_emit_family(self):
		keys, light, dark = Emitter.KEYS, Emitter.LIGHT, Emitter.DARK
		for family, scheme in (("base", True), ("palette", False)):
			full = emit.emit_family(family, keys, light, dark, color_scheme=scheme)
			only = emit.emit_light_family(family, keys, light, color_scheme=scheme)
			self.assertTrue(full.startswith(only))


class ParserHelpers(unittest.TestCase):
	def test_parse_blocks_handles_media_and_comments(self):
		blocks = parity.parse_blocks(
			"// c\n/* d */\na, b { --x: 1; }\n@media (m) {\n\tc { --y: rgba(1, 2, 3, 0.5); }\n}\n"
		)
		self.assertEqual(blocks[0].selectors, ("a", "b"))
		self.assertEqual(blocks[1].media, "(m)")
		self.assertEqual(blocks[1].declarations, [("--y", "rgba(1, 2, 3, 0.5)")])

	def test_unbalanced_braces_raise(self):
		with self.assertRaises(ValueError):
			parity.parse_blocks("a { --x: 1;")


if __name__ == "__main__":
	unittest.main()
